/**
 * dsh-jenkins —— 设置 → 「配置」tab：服务器管理 + 项目配置入口。
 *
 * 版面刻意保持轻量：
 * - **服务器**：列表 + 增删改（编辑在 ServerEditorModal 弹框里）+「配置模板」按钮；
 * - **项目配置**：一行摘要（`dsh-jenkins-map.json · N 个项目`），编辑集中在
 *   ProjectMapModal 弹框里 —— 内容大多由各工作区根目录的 dsh-jenkins.{json,js,ts}
 *   自动发现合并而来，通常无需手工维护。
 */

import { useCallback, useEffect, useMemo, useState } from 'react'
import { t, tErr } from '../i18n.ts'
import type { RunFn } from '../rpc.ts'
import { projectOpError, sanitizeProjects, type ProjectConfigMap } from '../projects.ts'
import { ProjectMapModal } from './ProjectMapModal.tsx'
import { ServerEditorModal } from './ServerEditorModal.tsx'
import type { PublicServer } from './ServerEditorModal.tsx'
import { TemplateModal } from './TemplateModal.tsx'
import { ShowInMenuToggle } from './ShowInMenuToggle.tsx'

interface TestResult {
  ok: boolean
  text: string
}

export interface SettingsPageProps {
  run: RunFn
  sessionId: string
  /** 当前工作区（模板「保存到工作区」的默认目标根目录）。 */
  cwd?: string
  /** 已打开的工作区列表（与统一弹框的 useWorkspaces 返回形状一致）。 */
  workspaceItems?: Array<{ path?: string; sessionIds?: string[] }>
  onCountChange?: (count: number) => void
}

export function SettingsPage({ run, sessionId, cwd, workspaceItems, onCountChange }: SettingsPageProps) {
  const [servers, setServers] = useState<PublicServer[]>([])
  const [loading, setLoading] = useState(true)
  const [editor, setEditor] = useState<{ open: boolean; server: PublicServer | null }>({ open: false, server: null })
  const [testResults, setTestResults] = useState<Record<string, TestResult>>({}) // 每台服务器的测试结果（显示在卡片名称后）
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null)
  const [templateOpen, setTemplateOpen] = useState(false)
  // 集中式项目配置（dsh-jenkins-map.json）：列表只显示一行摘要，编辑在弹框里
  const [projectMap, setProjectMap] = useState<ProjectConfigMap>({})
  const [mapPath, setMapPath] = useState('')
  const [mapError, setMapError] = useState('')
  const [mapOpen, setMapOpen] = useState(false)
  // 工作区路径（去空去重）：作为「发现式配置」的扫描范围
  const workspaces = useMemo(() => [...new Set((Array.isArray(workspaceItems) ? workspaceItems : [])
    .map((w) => (w && typeof w.path === 'string' ? w.path : ''))
    .filter((p): p is string => p !== ''))], [workspaceItems])
  const workspacesKey = workspaces.join('\n')

  const load = () => {
    setLoading(true)
    run(sessionId, { op: 'list' }).then((r) => {
      if (r && r.ok) {
        const list = (r.servers as PublicServer[]) || []
        setServers(list)
        if (onCountChange) onCountChange(list.length)
      }
    }).catch(() => { }).finally(() => setLoading(false))
  }
  useEffect(() => { load() }, [])

  // 读取项目配置：宿主顺带把已打开工作区里新出现的 dsh-jenkins 配置发现进来（只补缺失）
  const loadMap = useCallback((): void => {
    const cwds = workspacesKey ? workspacesKey.split('\n') : []
    run(sessionId, { op: 'mapLoad', cwds }).then((r) => {
      if (r && r.ok) {
        setProjectMap(sanitizeProjects(r.map))
        setMapPath(String(r.path || ''))
        setMapError('')
      } else {
        setMapError(projectOpError(r, t('loading')))
      }
    }).catch((e) => setMapError(e instanceof Error ? e.message : String(e)))
  }, [run, sessionId, workspacesKey])
  useEffect(() => { loadMap() }, [loadMap])

  const projectNames = Object.keys(projectMap)

  const openAdd = () => {
    setEditor({ open: true, server: null })
  }
  const openEdit = (s: PublicServer) => {
    setEditor({ open: true, server: s })
  }
  const closeEditor = () => setEditor({ open: false, server: null })

  const doDelete = (id: string) => {
    if (confirmDeleteId !== id) { setConfirmDeleteId(id); return }
    setConfirmDeleteId(null)
    run(sessionId, { op: 'delete', id }).then((r) => { if (r && r.ok) load() })
  }
  const doTestSaved = (s: PublicServer) => {
    // 测试结果持久化在服务器配置（host 端 verified 字段）；此处同步本地状态即时反馈
    const applyVerified = (ok: boolean): void => {
      setServers((prev) => prev.map((x) => (x.id === s.id ? { ...x, verified: ok } : x)))
    }
    run(sessionId, { op: 'test', server: { id: s.id } })
      .then((r) => {
        const ok = !!(r && r.ok)
        applyVerified(ok)
        setTestResults((prev) => ({ ...prev, [s.id]: ok
          ? { ok: true, text: t('connected') + ((r.version as string) ? '（Jenkins ' + r.version + '）' : '') }
          : { ok: false, text: t('connectionFailed') + tErr(r, t('testFailed')) } }))
      })
      .catch((e) => {
        applyVerified(false)
        setTestResults((prev) => ({ ...prev, [s.id]: { ok: false, text: t('connectionFailed') + (e instanceof Error ? e.message : String(e)) } }))
      })
  }

  return (
    <div className="dshj-settings">
      {/* 「在菜单中显示」开关：与宿主「设置 → Jenkins 配置」分区页同一偏好源 */}
      <ShowInMenuToggle />
      <div className="dshj-head">
        <div className="dshj-title">{t('settingsTitle')}</div>
        <div className="dshj-head-ops">
          <button
            type="button"
            className="dshj-btn dshj-btn-small"
            title={t('addServer')}
            onClick={openAdd}
          >
            {t('addServer')}
          </button>
          <button
            type="button"
            className="dshj-btn dshj-btn-small"
            title={t('projectConfigBtn')}
            onClick={() => setTemplateOpen(true)}
          >
            {t('projectConfigBtn')}
          </button>
        </div>
      </div>
      {templateOpen ? (
        <TemplateModal
          run={run}
          sessionId={sessionId}
          cwd={cwd || ''}
          workspaces={workspaces}
          onClose={() => setTemplateOpen(false)}
        />
      ) : null}
      {editor.open ? (
        <ServerEditorModal
          run={run}
          sessionId={sessionId}
          server={editor.server}
          onSaved={() => load()} // 编辑保存后 host 已清除该服务器 verified，重新拉取列表
          onClose={closeEditor}
        />
      ) : null}
      {mapOpen ? (
        <ProjectMapModal
          run={run}
          sessionId={sessionId}
          servers={servers}
          workspaces={workspaces}
          mapPath={mapPath}
          initial={projectMap}
          onSaved={(next) => { setProjectMap(next); setMapError('') }}
          onClose={() => setMapOpen(false)}
        />
      ) : null}
      {loading ? <div className="dshj-empty">{t('loading')}</div>
        : servers.length === 0 ? (
          <div className="dshj-empty">
            <div>{t('serverEmpty')}</div>
            <button type="button" className="dshj-btn dshj-btn-small" onClick={openAdd} style={{ marginTop: 10 }}>{t('addServer')}</button>
          </div>
        ) : (
          <div className="dshj-list">
            {servers.map((s) => {
              // 名称后的连接状态：优先显示本次会话的测试结果（成功绿/失败红），
              // 无测试结果但有持久化 verified 时显示「连接成功」；其余不显示。
              const tr = testResults[s.id]
              const statusText = tr ? tr.text : (s.verified ? t('connected') : '')
              const statusOk = tr ? tr.ok : s.verified
              return (
                <div key={s.id} className="dshj-card">
                  <div className="dshj-card-main">
                    <div className="dshj-card-name-row">
                      <span className="dshj-card-name">{s.name}</span>
                      {statusText ? (
                        <span className={'dshj-card-test ' + (statusOk ? 'dshj-ok' : 'dshj-err')}>{statusText}</span>
                      ) : null}
                    </div>
                    <div className="dshj-card-meta">{s.baseUrl + '  ·  ' + s.username + '  ·  ' + (s.tokenMasked || '')}</div>
                  </div>
                  <div className="dshj-card-ops">
                    <button type="button" className="dshj-btn dshj-btn-small" onClick={() => doTestSaved(s)}>{t('testBtn')}</button>
                    <button type="button" className="dshj-btn dshj-btn-small" onClick={() => openEdit(s)}>{t('editBtn')}</button>
                    <button
                      type="button"
                      className={'dshj-btn dshj-btn-small dshj-btn-danger' + (confirmDeleteId === s.id ? ' dshj-btn-solid' : '')}
                      onClick={() => doDelete(s.id)}
                    >
                      {confirmDeleteId === s.id ? t('confirmDelete') : t('deleteBtn')}
                    </button>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      {/* 项目配置：一行摘要 + 编辑入口（内容 = 各工作区配置自动发现合并的结果） */}
      <div className="dshj-divider" />
      <div className="dshj-maprow" title={t('projectsHint')}>
        <div className="dshj-maprow-main">
          <div className="dshj-title">{t('projectsTitle')}</div>
          <div className="dshj-maprow-meta">{'dsh-jenkins-map.json · ' + t('projectCount', { n: projectNames.length })}</div>
        </div>
        <button type="button" className="dshj-btn dshj-btn-small" onClick={() => setMapOpen(true)}>{t('editMap')}</button>
      </div>
      {mapError ? <div className="dshj-err">{mapError}</div> : null}
    </div>
  )
}
